UPDATE WF_TERMINAL_EVENT_OUTBOX
SET STATUS='DELIVERED', CLAIMED_BY=NULL, CLAIMED_UNTIL=NULL, UPDATED_AT=#{updatedAt}
WHERE INSTANCE_ID=#{instanceId} AND STATUS='IN_PROGRESS'
  AND CLAIMED_BY=#{claimedBy} AND CLAIMED_UNTIL > #{claimedUntil}

UPDATE WF_TERMINAL_EVENT_OUTBOX
SET STATUS='PENDING', ATTEMPTS=#{attempts}, NEXT_ATTEMPT_AT=#{nextAttemptAt}, LAST_ERROR=#{lastError},
    CLAIMED_BY=NULL, CLAIMED_UNTIL=NULL, UPDATED_AT=#{updatedAt}
WHERE INSTANCE_ID=#{instanceId} AND STATUS='IN_PROGRESS'
  AND CLAIMED_BY=#{claimedBy} AND CLAIMED_UNTIL > #{claimedUntil}

UPDATE WF_TERMINAL_EVENT_OUTBOX
SET STATUS='DEAD', ATTEMPTS=#{attempts}, LAST_ERROR=#{lastError},
    CLAIMED_BY=NULL, CLAIMED_UNTIL=NULL, UPDATED_AT=#{updatedAt}
WHERE INSTANCE_ID=#{instanceId} AND STATUS='IN_PROGRESS'
  AND CLAIMED_BY=#{claimedBy} AND CLAIMED_UNTIL > #{claimedUntil}

UPDATE WF_TERMINAL_EVENT_OUTBOX SET STATUS='IN_PROGRESS', CLAIMED_BY=#{owner}, CLAIMED_UNTIL=#{until}, UPDATED_AT=#{now}
WHERE INSTANCE_ID IN #{id}
AND ((STATUS='PENDING' AND NEXT_ATTEMPT_AT <= #{now}) OR (STATUS='IN_PROGRESS' AND CLAIMED_UNTIL <= #{now}))
